INSERT INTO public.ai_tools (tool_id, app_name, url, short_description, category_1, category_2, category_3, tags, platforms, promo_code, featured_today, sponsored, star_rating, review_count, date_added, last_updated) VALUES
('marketing_ai_ads', 'Ai-Ads', 'https://www.adcreative.ai/?utm_id=22364675724&utm_source=google&utm_medium=paid&utm_campaign=adc_search_generic_us_eg_conv&utm_content=741370258553&utm_term=ai%20ads&utm_placement=&utm_ad_group=175331717405&utm_creative_format=search&campaignid=22364675724&adgroupid=175331717405&keyword=ai%20ads&device=c&gad_source=1&gad_campaignid=22364675724&gbraid=0AAAAA98jT3lMdB3nXMj1yhEu1k-9vWYry&gclid=Cj0KCQiAgvPKBhCxARIsAOlK_EpPoUUaTqc5wTfYrHgpI-65DkLvKF5FNN5Ew8UBZZyux_hoy-KJkisaAmjCEALw_wcB', 'Generates ad creatives and variations optimized for performance marketing.', 'Design & Branding', 'Revenue (Sales & Commerce)', 'Marketing & SEO', ARRAY['Forms / intake', 'SEO', 'Ads creative'], NULL, NULL, false, false, 4.6, 2341, '2026-01-05', '2026-01-05'),
('prompts_alicent_ai', 'Alicent AI', 'https://alicent.ai/', 'Prompt/workflow helper for generating and organizing prompt templates.', 'Design & Branding', 'Automation & Agents (Workflows)', NULL, ARRAY['Automation workflows', 'Templates'], NULL, NULL, false, false, 4.3, 892, '2026-01-05', '2026-01-05'),
('tool_bloggify', 'Bloggify', 'https://bloggify.org/', 'With Bloggify you can build that amazing application you have been dreaming of.', 'Design & Branding', 'Writing & Copywriting', NULL, ARRAY[]::text[], NULL, NULL, false, false, 4.1, 456, CURRENT_DATE, CURRENT_DATE),
('blaze_ai', 'Blaze AI', 'https://www.blaze.ai/home?utm_source=google&utm_medium=cpc&utm_campaign=22897803571&utm_content=185374717162&utm_term=ai%20content%20maker&gad_source=1&gad_campaignid=22897803571&gbraid=0AAAAAqFULdNTMsH6Mj7IuZmnQM4msBGIh&gclid=Cj0KCQiAgvPKBhCxARIsAOlK_EpXe4EGmQ75ne-ukFL39dcKIqS6rJSJ3rq7VDy2m9bQ8m7kzzhufYgaAugZEALw_wcB', 'The AI marketing platform with taste, power, and speed — turning strategy into content and insights into growth.', 'Marketing & SEO', 'Docs, Forms & Data Capture', NULL, ARRAY['Forms / intake', 'SEO'], NULL, NULL, false, false, 4.7, 1823, '2026-01-05', '2026-01-05'),
('tool_bluegpt', 'BlueGPT', 'https://bluegpt.app/', 'Generate content automatically, create personal AI Agents, analyze your documents, and save hundreds of hours with unprecedented features.', 'Chatbots & Assistants', 'Docs, Forms & Data Capture', NULL, ARRAY['Agentic / autonomous', 'Document / PDF tools'], NULL, NULL, false, false, 4.4, 1234, CURRENT_DATE, CURRENT_DATE),
('tool_cluey', 'Cluey', 'https://cluely.com/', 'Cluely takes perfect meeting notes and gives real-time answers, all while completely undetectable', 'Meetings (Transcription & Action Items)', 'Productivity & Notes', NULL, ARRAY['Meeting notes'], NULL, NULL, false, false, 4.2, 678, '2026-01-05', '2026-01-05'),
('tool_color_anything', 'Color Anything', 'https://color-anything.com/', 'AI-powered tool that generates customizable coloring pages from images or user input, allowing people to create personalized art, while "color" itself is the perception of light reflecting off objects, influencing psychology and design. The AI tool, available as apps or online, simplifies the process for users of all ages to engage with coloring activities, turning anything into a potential coloring page', 'Images (Create & Edit)', 'Design & Branding', NULL, ARRAY[]::text[], NULL, NULL, false, false, 3.9, 234, CURRENT_DATE, CURRENT_DATE),
('tool_comet', 'Comet (perpelxity browser)', 'https://www.perplexity.ai/comet', 'Perplexity Comet is an AI-native web browser from Perplexity AI that integrates a powerful AI assistant directly into browsing, allowing it to perform complex tasks, manage tabs, summarize content, draft emails, and even shop or book travel by "driving" the browser like a personal agent, offering "agentic browsing" to automate workflows and enhance productivity beyond traditional search.', 'Research & Knowledge', 'Automation & Agents (Workflows)', 'Chatbots & Assistants', ARRAY['Automation workflows', 'Agentic / autonomous', 'Summarizer', 'Forms / intake'], NULL, NULL, true, false, 4.8, 3421, '2026-01-05', '2026-01-05'),
('image_dalle_3', 'Dalle 3', 'https://openai.com/index/dall-e-3/', 'Modern text-to-image systems have a tendency to ignore words or descriptions, forcing users to learn prompt engineering. DALL·E 3 represents a leap forward in our ability to generate images that exactly adhere to the text you provide.', 'Images (Create & Edit)', 'Video (Create & Edit)', 'Audio / Voice / Music', ARRAY['Video editor', 'Image generator'], NULL, NULL, false, false, 4.9, 4567, '2026-01-05', '2026-01-05'),
('chatbot_tool_dante_ai', 'Dante AI', 'https://dante-ai.com/', 'Handle unlimited conversations simultaneously across chat and voice while your team focuses on high-value work. Test it free on your site. 60 seconds setup, no card needed.', 'Audio / Voice / Music', NULL, NULL, ARRAY[]::text[], NULL, NULL, false, false, 4.5, 1890, '2026-01-05', '2026-01-05');
INSERT INTO public.ai_tools (tool_id, app_name, url, short_description, category_1, category_2, category_3, tags, platforms, star_rating, review_count, date_added) VALUES
('chatgpt', 'ChatGPT', 'https://chatgpt.com/', 'ChatGPT is an advanced AI chatbot from OpenAI that uses large language models (LLMs) to understand prompts and generate human-like text for conversations, writing, coding, research, and more, mimicking human intelligence by predicting the most probable words in a sequence after extensive training on vast text datasets.', 'Chatbots & Assistants', 'Research & Knowledge', 'Writing & Copywriting', ARRAY[]::text[], NULL, 4.8, 15234, '2026-01-05'),
('claude', 'Claude', 'https://claude.ai/', 'Claude, developed by Anthropic, is a family of large language models that can be interacted with directly or used by developers to build other AI applications. With Claude, you can have conversations, brainstorm ideas, and analyze documents.', 'Coding & Developer Tools', 'Design & Branding', 'Chatbots & Assistants', ARRAY['Document / PDF tools'], NULL, 4.7, 12456, '2026-01-05'),
('midjourney', 'Midjourney', 'https://www.midjourney.com/', 'Midjourney is an AI image generation service that creates images from text descriptions. It uses machine learning to produce artistic and photorealistic images.', 'Images (Create & Edit)', 'Design & Branding', NULL, ARRAY['Image generator'], NULL, 4.9, 23456, '2026-01-05'),
('cursor_ide', 'Cursor', 'https://www.cursor.com/', 'AI coding IDE for editing, refactoring, and shipping code with assistant workflows.', 'Coding & Developer Tools', 'App & App Builder / Support', 'Automation & Agents (Workflows)', ARRAY['Automation workflows'], NULL, 4.8, 8234, '2026-01-05'),
('canva', 'Canva AI', 'https://www.canva.com', 'AI-assisted design for social posts, decks, brand kits, and quick creative production.', 'Design & Branding', 'Presentations', NULL, ARRAY['Brand kit', 'Presentation builder'], NULL, 4.7, 19834, '2026-01-05');
